-- UNIX, часть 4 из 4
update public.games set file_html = file_html || $cpx$", a6: "data:image/webp;base64,", a8: "data:image/webp;base64," };

const $ = (id) => document.getElementById(id);
// иконки меню — тот же набор, что в Stick Fight
