};
const lsG = (k) => { try { return localStorage.getItem(k); } catch (e) { return null; } };
const lsS = (k, v) => { try { localStorage.setItem(k, v); } catch (e) { } };
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => "&#" + c.charCodeAt(0) + ";");
const rnd = (a, b) => a + Math.random() * (b - a);
function shuffle(a) { for (let i = a.length - 1; i > 0; i--) { const j = Math.random() * (i + 1) | 0; [a[i], a[j]] = [a[j], a[i]]; } return a; }
const COLORS = ["r", "y", "g", "b"];
const CNAME = { r: "красный", y: "жёлтый", g: "зелёный", b: "синий" };
const CHEX = { r: "#ff3b30", y: "#ffcc00", g: "#34c759", b: "#1e7bff" };
const key = (c) => c.c + c.v;

/* ===================== ASSETS: slice atlases ===================== */
// rects found by scanning the atlases (x, y, w, h)
const R1 = [[27,55,142,203],[180,55,140,203],[332,55,139,203],[482,55,137,203],[630,55,137,203],[779,54,136,204],[926,54,136,204],[1073,54,137,204],[1221,54,139,204],[1371,54,138,204],[27,269,142,209],[180,269,140,209],[331,269,140,209],[482,269,137,209],[631,269,136,209],[779,269,136,209],[926,269,136,209],[1073,269,137,209],[1221,269,139,209],[1371,269,138,209],[27,495,142,217],[181,495,140,217],[332,495,139,217],[483,495,137,217],[631,495,136,217],[779,495,136,216],[926,495,137,216],[1073,495,137,216],[1221,495,139,216],[1371,495,138,216],[27,735,143,215],[182,735,139,215],[332,735,139,215],[482,735,138,215],[631,735,137,215],[779,735,136,215],[926,735,137,215],[1073,735,137,215],[1221,735,139,215],[1371,735,138,215]];
const R6 = { r: [26,38,144,213], y: [25,268,144,217], g: [26,501,144,219], b: [26,740,144,218] };
const R8 = { F: [926,32,266,431], W: [1224,32,278,432] };
const R5 = { D: [28,118,310,295], R: [356,98,256,320], S: [636,126,296,296] };
const R2 = { trophy: [26,762,204,190], gift: [1132,18,256,268], mega: [42,535,196,190], play: [486,540,160,176] };

const IMG = {}, ICO = {};
const loadImg = (src) => new Promise((res, rej) => { const i = new Image(); i.onload = () => res(i); i.onerror = rej; i.src = src; });
function cv(w, h) { const c = document.createElement("canvas"); c.width = w; c.height = h; return c; }
function rr(g, x, y, w, h, r) { g.beginPath(); g.moveTo(x + r, y); g.arcTo(x + w, y, x + w, y + h, r); g.arcTo(x + w, y + h, x, y + h, r); g.arcTo(x, y + h, x, y, r); g.arcTo(x, y, x + w, y, r); g.closePath(); }
// remove the white background of a sticker atlas (flood fill from the borders)
function cutBg(img, th) {
  const W = img.width, H = img.height, c = cv(W, H), g = c.getContext("2d");
  g.drawImage(img, 0, 0);
  const id = g.getImageData(0, 0, W, H), d = id.data, m = new Uint8Array(W * H), q = new Int32Array(W * H);
  let n = 0;
  const push = (i) => { if (m[i]) return; const r = d[i * 4], gg = d[i * 4 + 1], b = d[i * 4 + 2], mn = Math.min(r, gg, b); if (mn > th && Math.max(r, gg, b) - mn < 34) { m[i] = 1; q[n++] = i; } };
  for (let x = 0; x < W; x++) { push(x); push((H - 1) * W + x); }
  for (let y = 0; y < H; y++) { push(y * W); push(y * W + W - 1); }
  while (n) { const i = q[--n], x = i % W; d[i * 4 + 3] = 0; if (x > 0) push(i - 1); if (x < W - 1) push(i + 1); if (i >= W) push(i - W); if (i < W * (H - 1)) push(i + W); }
  g.putImageData(id, 0, 0);
  return c;
}
function crop(src, r) { const c = cv(r[2], r[3]); c.getContext("2d").drawImage(src, r[0], r[1], r[2], r[3], 0, 0, r[2], r[3]); return trim(c); }
function trim(c) { // shrink to the visible pixels
  const g = c.getContext("2d"), d = g.getImageData(0, 0, c.width, c.height).data;
  let x0 = c.width, y0 = c.height, x1 = 0, y1 = 0;
  for (let y = 0; y < c.height; y++) for (let x = 0; x < c.width; x++) if (d[(y * c.width + x) * 4 + 3] > 40) { if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }
  if (x1 <= x0) return c;
  const o = cv(x1 - x0 + 1, y1 - y0 + 1); o.getContext("2d").drawImage(c, -x0, -y0); return o;
}
function fit(g, ic, cx, cy, mw, mh, rot) { const s = Math.min(mw / ic.width, mh / ic.height), w = ic.width * s, h = ic.height * s; g.save(); g.translate(cx, cy); if (rot) g.rotate(rot); g.drawImage(ic, -w / 2, -h / 2, w, h); g.restore(); }
const CW = 160, CH = 240, FONT = "900 34px Rubik, 'Arial Black', Arial, sans-serif";
function outText(g, t, x, y, size, fill, rot) {
  g.save(); g.translate(x, y); if (rot) g.rotate(rot);
  g.font = FONT.replace("34px", size + "px"); g.textAlign = "center"; g.textBaseline = "middle";
  g.lineJoin = "round"; g.lineWidth = size * .22; g.strokeStyle = "#000"; g.strokeText(t, 0, 0);
  g.fillStyle = fill; g.fillText(t, 0, 0); g.restore();
}
function cardCanvas(fn) { const c = cv(CW, CH), g = c.getContext("2d"); g.save(); rr(g, 0, 0, CW, CH, 15); g.clip(); fn(g); g.restore(); return c.toDataURL("image/webp", .92); }

async function buildAssets() {
  try { await Promise.race([document.fonts.load(FONT), new Promise((r) => setTimeout(r, 2500))]); } catch (e) { }
  const [a1, a2, a3, a5, a6, a8] = await Promise.all([ATL.a1, ATL.a2, ATL.a3, ATL.a5, ATL.a6, ATL.a8].map(loadImg));
  $("bg").style.backgroundImage = "url(" + ATL.a3 + ")";
  // number cards 0-9
  COLORS.forEach((c, row) => { for (let v = 0; v < 10; v++) { const r = R1[row * 10 + v]; IMG[c + v] = cardCanvas((g) => g.drawImage(a1, r[0] + 1, r[1] + 1, r[2] - 2, r[3] - 2, 0, 0, CW, CH)); } });
  // action cards: blank colored card + sticker icon
  const s5 = cutBg(a5, 200), ic = {}; for (const k in R5) ic[k] = crop(s5, R5[k]);
  for (const c of COLORS) {
    const r = R6[c];
    for (const v of ["S", "R", "D"]) {
      IMG[c + v] = cardCanvas((g) => {
        g.drawImage(a6, r[0] + 1, r[1] + 1, r[2] - 2, r[3] - 2, 0, 0, CW, CH);
        fit(g, ic[v], CW / 2, CH / 2, CW * .74, CH * .5, v === "R" ? 0 : -.12);
        if (v === "D") { outText(g, "+2", 30, 30, 30, "#fff"); outText(g, "+2", CW - 30, CH - 30, 30, "#fff", Math.PI); }
        else { fit(g, ic[v], 28, 30, 42, 42); fit(g, ic[v], CW - 28, CH - 30, 42, 42, Math.PI); }
      });
    }
  }
  // wild cards from the black atlas
  for (const v of ["W", "F"]) { const r = R8[v]; IMG["k" + v] = cardCanvas((g) => g.drawImage(a8, r[0] + 3, r[1] + 3, r[2] - 6, r[3] - 6, 0, 0, CW, CH)); }
  // card back: dark glossy card + game name
  IMG.back = cardCanvas((g) => {
    const r = R6.r; g.drawImage(a6, r[0] + 1, r[1] + 1, r[2] - 2, r[3] - 2, 0, 0, CW, CH);
    g.fillStyle = "rgba(20,0,40,.35)"; g.fillRect(0, 0, CW, CH);
    g.save(); g.translate(CW / 2, CH / 2); g.rotate(-.5); g.scale(1, .55); g.beginPath(); g.arc(0, 0, 70, 0, 7); g.restore();
    g.fillStyle = "#ffd92e"; g.fill(); g.lineWidth = 5; g.strokeStyle = "#000"; g.stroke();
    outText(g, "UNIX", CW / 2, CH / 2 + 2, 36, "#e8231b", -.5);
  });
  const s2 = cutBg(a2, 214); for (const k in R2) ICO[k] = crop(s2, R2[k]).toDataURL();
}

/* ===================== SOUND ===================== */
let AC = null, SND = lsG("vSnd") !== "0";
function beep(f, d, type, v, slide, delay) {
  if (!SND) return;
  try {
    AC = AC || new (window.AudioContext || window.webkitAudioContext)();
    const t = AC.currentTime + (delay || 0), o = AC.createOscillator(), g = AC.createGain();
    o.type = type || "sine"; o.frequency.setValueAtTime(f, t); if (slide) o.frequency.exponentialRampToValueAtTime(f * slide, t + d);
    g.gain.setValueAtTime(v || .12, t); g.gain.exponentialRampToValueAtTime(.001, t + d);
    o.connect(g).connect(AC.destination); o.start(t); o.stop(t + d + .02);
  } catch (e) { }
}
const SFX = {
  play: () => beep(480, .1, "triangle", .16, 1.6),
  draw: () => beep(320, .07, "sine", .1, .7),
  turn: () => { beep(660, .1, "triangle", .14); beep(990, .14, "triangle", .14, 0, .1); },
  call: () => { beep(520, .12, "square", .08, 1.5); beep(780, .18, "square", .08, 1.5, .12); },
  bad: () => beep(200, .3, "sawtooth", .08, .5),
  win: () => [523, 659, 784, 1046].forEach((f, i) => beep(f, .2, "triangle", .14, 0, i * .13)),
  pop: () => beep(800, .05, "sine", .08),
};

/* ===================== UI helpers ===================== */
function show(sc) { for (const s of ["scMenu", "scRoom", "scGame"]) $(s).classList.toggle("on", s === sc); if (sc !== "scGame") $("emoBar").classList.remove("on"); }
function modal(html) { $("mBody").innerHTML = html; $("modal").classList.add("on"); }
function closeModal() { $("modal").classList.remove("on"); }
function toast(t) { const d = document.createElement("div"); d.textContent = t; $("toast").appendChild(d); setTimeout(() => d.remove(), 2600); while ($("toast").children.length > 3) $("toast").firstChild.remove(); }
function banner(t) { const b = $("banner"); b.textContent = t; b.classList.remove("on"); void b.offsetWidth; b.classList.add("on"); }
const myName = () => (($("inName").value || "").trim() || lsG("vName") || "Игрок").slice(0, 16);
const AVC = ["#ff6a5e", "#4cb8ff", "#86ec3c", "#b866ff", "#ffab0a"];
function avatar(name, i, bot) { return '<div class="av" style="background:' + AVC[i % 5] + '">' + (bot ? "🤖" : esc((name || "?")[0].toUpperCase())) + '<div class="ring"></div></div>'; }
function rules() {
  modal('<h2>Правила игры «UNIX»</h2><div class="rules">' +
    '<p>Цель — первым избавиться от всех карт. Клади карту того же <b>цвета</b> или того же <b>значения</b>, что и верхняя карта сброса.</p>' +
    '<p><b>⊘ Пропуск</b> — следующий игрок пропускает ход. <b>⇄ Разворот</b> — меняет направление (вдвоём работает как пропуск). <b>+2</b> — следующий берёт 2 карты и пропускает ход.</p>' +
    '<p><b>Смена цвета</b> — кладётся на что угодно, ты выбираешь цвет. <b>+4</b> — то же, и следующий берёт 4.</p>' +
    '<p>Нечем ходить — нажми на колоду и возьми карту. Если она подходит — можно сразу сыграть, иначе «Пас».</p>' +
    '<p><b>UNIX!</b> — когда у тебя остаётся одна карта, жми кнопку. Не успел, а соперник нажал «Поймать!» — берёшь 2 карты.</p>' +
    '<p><b>Стопки</b> (если включены): на +2 можно ответить +2 или +4, на +4 — +4; штраф копится.</p>' +
    '<p><b>Кооп «Люди против ботов»:</b> все игроки — одна команда. Победа, если любой из вас выйдет первым. Вы видите карты союзников, а раз за раунд можно <b>подарить</b> карту союзнику (вместо хода), чтобы помочь лидеру.</p>' +
    '</div><div class="mbt"><button class="ub pr" onclick="closeModal()"><i class="ic">' + ICON.check + '</i>Понятно</button></div>');
}

/* ===================== NETWORK (WebRTC, signalling via ntfy.sh) ===================== */
// the same approach as Грязеход: short service messages go through ntfy.sh,
// the game itself runs over a direct WebRTC data channel; the host is the authority.
const NT = "https://ntfy.sh/";
const ICE = [{ urls: ["stun:stun.l.google.com:19302", "stun:stun.cloudflare.com:3478", "stun:stun.nextcloud.com:3478"] },
  { urls: ["turn:openrelay.metered.ca:80", "turn:openrelay.metered.ca:443", "turn:openrelay.metered.ca:443?transport=tcp"], username: "openrelayproject", credential: "openrelayproject" }];
function h53(s) { let a = 0xdeadbeef, b = 0x41c6ce57; for (let i = 0; i < s.length; i++) { const c = s.charCodeAt(i); a = Math.imul(a ^ c, 2654435761); b = Math.imul(b ^ c, 1597334677); } a = Math.imul(a ^ a >>> 16, 2246822507) ^ Math.imul(b ^ b >>> 13, 3266489909); b = Math.imul(b ^ b >>> 16, 2246822507) ^ Math.imul(a ^ a >>> 13, 3266489909); return (4294967296 * (2097151 & b) + (a >>> 0)).toString(36); }
function sse(topic, since, fn, onerr) { const es = new EventSource(NT + topic + "/sse" + (since ? "?since=" + since : "")); es.addEventListener("message", (e) => { try { fn(JSON.parse(JSON.parse(e.data).message)); } catch (x) { } }); if (onerr) es.onerror = onerr; return es; }
const pub = (t, o) => fetch(NT + t, { method: "POST", body: JSON.stringify(o) });
async function zip(s) { try { if (!window.CompressionStream) throw 0; const b = new Uint8Array(await new Response(new Blob([s]).stream().pipeThrough(new CompressionStream("deflate-raw"))).arrayBuffer()); let t = ""; for (const x of b) t += String.fromCharCode(x); return "z" + btoa(t); } catch (e) { return "r" + s; } }
async function unzip(s) { if (s[0] === "r") return s.slice(1); const b = Uint8Array.from(atob(s.slice(1)), (c) => c.charCodeAt(0)); return await new Response(new Blob([b]).stream().pipeThrough(new DecompressionStream("deflate-raw"))).text(); }
function makePeer(pc, on) {
  const p = { pc, ch: null, open: false, send(m) { const d = p.ch; if (d && d.readyState === "open") try { d.send(JSON.stringify(m)); } catch (e) { } }, close() { try { pc.close(); } catch (e) { } lost(); } };
  const lost = () => { if (p.open) { p.open = false; on.close(p); } };
  const opened = () => { if (!p.open) { p.open = true; on.open(p); } };
  p.bind = (d) => { p.ch = d; d.onmessage = (e) => { let m; try { m = JSON.parse(e.data); } catch (x) { return; } on.msg(m, p); }; d.onopen = opened; d.onclose = lost; if (d.readyState === "open") opened(); };
  pc.onconnectionstatechange = () => { const s = pc.connectionState; clearTimeout(p.dt); if (s === "failed" || s === "closed") lost(); else if (s === "disconnected") p.dt = setTimeout(() => { if (pc.connectionState !== "connected") lost(); }, 15000); };
  return p;
}
const gather = (pc) => new Promise((r) => { if (pc.iceGatheringState === "complete") return r(); let rel = 0; pc.addEventListener("icegatheringstatechange", () => pc.iceGatheringState === "complete" && r()); pc.addEventListener("icecandidate", (e) => { if (e.candidate && / typ relay/.test(e.candidate.candidate) && !rel++) setTimeout(r, 600); }); setTimeout(r, 6000); });
async function rtcOffer(on) { const pc = new RTCPeerConnection({ iceServers: ICE }), p = makePeer(pc, on); p.bind(pc.createDataChannel("g")); await pc.setLocalDescription(await pc.createOffer()); await gather(pc); return { p, sdp: pc.localDescription.sdp, finish: (sdp) => pc.setRemoteDescription({ type: "answer", sdp }) }; }
async function rtcAnswer(sdp, on) { const pc = new RTCPeerConnection({ iceServers: ICE }), p = makePeer(pc, on); pc.ondatachannel = (e) => p.bind(e.channel); await pc.setRemoteDescription({ type: "offer", sdp }); await pc.setLocalDescription(await pc.createAnswer()); await gather(pc); return { p, sdp: pc.localDescription.sdp }; }

let role = "none"; // none | solo | host | guest
let L = null;      // room/lobby (host is the authority, guests get copies)
let G = null;      // game state (host only)
let V = null;      // what this screen shows
const peers = new Map(); // host: pid -> peer
let hostPeer = null;
const NET = { es: null, st: "", rooms: new Map(), word: "", quick: 0, qtry: 0, joining: 0, hes: null, ann: 0, seen: new Set(), err: "", prune: 0, ans: null };
const lobbyTopic = () => "vihr1-l-" + h53("lobby|" + NET.word);
const roomTopic = (code) => "vihr1-r-" + h53("room|" + code);
const CODEA = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
const genCode = () => { let s = ""; for (let i = 0; i < 5; i++) s += CODEA[Math.random() * CODEA.length | 0]; return s; };

function netOpen() {
  const w = ($("inWord").value || "").trim().toLowerCase();
  if (NET.es && NET.word === w) return;
  netCloseList();
  NET.word = w; NET.st = "conn"; NET.err = ""; menuUI();
  NET.es = sse(lobbyTopic(), "45s", (m) => {
    if (m.k === "room" && m.id) { NET.rooms.set(m.id, { id: m.id, name: String(m.name || "").slice(0, 16), n: m.n | 0, mx: m.mx | 0 || 4, st: m.st, seen: Date.now() }); menuUI(); tieBreak(); }
    else if (m.k === "gone") { NET.rooms.delete(m.id); menuUI(); }
  }, () => { if (NET.st !== "open") { NET.err = "Нет связи с сервисом поиска (ntfy.sh). Проверьте интернет."; menuUI(); } });
  NET.es.onopen = () => { NET.st = "open"; NET.err = ""; menuUI(); if (NET.quick) setTimeout(quickDecide, 1800); };
  NET.prune = setInterval(() => { const t = Date.now(); let ch = 0; for (const [k, r] of NET.rooms) if (t - r.seen > 40e3) { NET.rooms.delete(k); ch = 1; } if (ch) menuUI(); }, 4e3);
}
function netCloseList() { try { NET.es && NET.es.close(); } catch (e) { } clearInterval(NET.prune); NET.es = null; NET.st = ""; NET.rooms.clear(); }

/* ---- host side ---- */
function newLobby(code) { return { code, mode: "coop", total: 4, stack: true, members: [{ pid: "h", name: myName() }], started: false, score: {} }; }
function hostOnline(fromQuick, via) {
  if (role !== "none") return;
  lsS("vName", myName());
  NET.hostVia = via || (fromQuick ? "online" : "code"); closeWins();
  if (!NET.es) netOpen();
  const code = genCode();
  role = "host"; L = newLobby(code); NET.quickHost = !!fromQuick; NET.seen = new Set();
  NET.hes = sse(roomTopic(code), "20s", async (m) => {
    if (m.k !== "offer" || !m.g || NET.seen.has(m.g) || role !== "host") return;
    NET.seen.add(m.g);
    if (L.members.length >= 4) { pub(roomTopic(code) + "-" + m.g, { k: "full" }).catch(() => { }); return; }
    try {
      const r = await rtcAnswer(await unzip(m.sdp), hostH);
      r.p.pid = m.g; r.p.nm = String(m.name || "Игрок").slice(0, 16);
      await pub(roomTopic(code) + "-" + m.g, { k: "answer", sdp: await zip(r.sdp) });
      setTimeout(() => { if (!r.p.open) r.p.close(); }, 40e3);
    } catch (e) { console.warn(e); }
  });
  advertise(); NET.ann = setInterval(advertise, 12e3);
  show("scRoom"); renderRoom();
}
function advertise() { if (role === "host" && L) pub(lobbyTopic(), { k: "room", id: L.code, name: L.members[0].name, n: L.members.length, mx: 4, st: L.started ? "game" : "lobby" }).catch(() => { }); }
function unhost() { clearInterval(NET.ann); try { NET.hes && NET.hes.close(); } catch (e) { } NET.hes = null; if (L && L.code) pub(lobbyTopic(), { k: "gone", id: L.code }).catch(() => { }); }
const hostH = {
  open(p) {
    if (L.members.length >= 4) { p.send({ k: "bye", why: "Комната заполнена" }); setTimeout(() => p.close(), 300); return; }
    peers.set(p.pid, p);
    L.members.push({ pid: p.pid, name: p.nm });
    recSave("host", NET.hostVia || "code", p.nm);
    SFX.pop();
    if (G) { // mid-game: take back your seat if you dropped out
      const s = G.seats.find((x) => x.off && x.name === p.nm);
      if (s) { s.pid = p.pid; s.off = false; G.ev.push({ t: "back", s: G.seats.indexOf(s) }); }
      else toastAll(p.nm + " наблюдает — сядет в следующем раунде");
    }
    toastLocal(p.nm + " в комнате");
    sendLobby(); if (G) broadcastState(); advertise();
  },
  msg(m, p) { hostRecv(p.pid, m); },
  close(p) {
    if (!peers.has(p.pid)) return;
    peers.delete(p.pid);
    if (!L || role !== "host") return; // the host already left the room
    L.members = L.members.filter((x) => x.pid !== p.pid);
    if (G) { const s = G.seats.find((x) => x.pid === p.pid); if (s) { s.off = true; s.pid = null; G.ev.push({ t: "left", s: G.seats.indexOf(s) }); G.turnMs = G.seats.some((x) => x.kind === "human" && x.pid && x.pid !== "h") ? 30000 : 0; } }
    toastLocal(p.nm + " вышел");
    sendLobby(); if (G) broadcastState(); advertise();
  },
};
function hostRecv(pid, m) {
  if (m.k === "act" && G) { const s = G.seats.findIndex((x) => x.pid === pid); if (s >= 0) act(s, m); }
  else if (m.k === "emo") hostEmo(pid, m.e);
}
const lastEmo = {};
function hostEmo(pid, e) {
  if (!EMOS.includes(e) || Date.now() - (lastEmo[pid] || 0) < 700) return;
  lastEmo[pid] = Date.now();
  const s = G ? G.seats.findIndex((x) => x.pid === pid) : -1;
  if (s < 0) return;
  for (const p of peers.values()) p.send({ k: "emo", s, e });
  showEmo(s, e);
}
function toastLocal(t) { if ($("scGame").classList.contains("on")) toast(t); }
function toastAll(t) { for (const p of peers.values()) p.send({ k: "toast", t }); toastLocal(t); }
const lobbyPub = () => ({ code: L.code, mode: L.mode, total: L.total, stack: L.stack, members: L.members.map((m) => ({ name: m.name, pid: m.pid })), started: L.started, score: L.score });
function sendLobby() { const o = lobbyPub(); for (const p of peers.values()) p.send({ k: "lobby", L: o }); if (!L.started) { renderRoom(); } }

/* ---- guest side ---- */
async function guestJoin(code, via) {
  code = String(code || "").toUpperCase().replace(/[^A-Z0-9]/g, "");
  if (role !== "none" || NET.joining) return;
  if (code.length !== 5) { NET.err = "Код комнаты — 5 символов (буквы и цифры)."; menuUI(); return; }
  const hostNm = (NET.rooms.get(code) || {}).name || "";
  lsS("vName", myName());
  NET.joining = 1; NET.err = ""; menuUI();
  const g = Math.random().toString(36).slice(2, 10), rt = roomTopic(code);
  let done = 0, r = null;
  const fail = (msg) => { if (done > 1) return; done = 2; NET.joining = 0; try { NET.ans && NET.ans.close(); } catch (e) { } if (r) r.p.close(); NET.err = msg; menuUI(); quickRetry(code); };
  NET.ans = sse(rt + "-" + g, "30s", async (m) => {
    if (m.k === "full") fail("Комната заполнена");
    else if (m.k === "answer" && !done && r) { done = 1; try { NET.ans.close(); await r.finish(await unzip(m.sdp)); } catch (e) { fail("Ошибка: " + e.message); } }
  });
  const gh = {
    open(p) { role = "guest"; hostPeer = p; NET.joining = 0; NET.quick = 0; done = 3; recSave("guest", via || "code", hostNm); netCloseList(); closeWins(); show("scRoom"); $("rTitle").textContent = "Подключено…"; },
    msg(m) { guestRecv(m); },
    close() { if (role === "guest") leave("Соединение с хостом потеряно"); },
  };
  try { r = await rtcOffer(gh); await pub(rt, { k: "offer", g, name: myName(), sdp: await zip(r.sdp) }); }
  catch (e) { fail("Ошибка: " + e.message); return; }
  setTimeout(() => { if (role !== "guest" && done < 2) fail("Не удалось подключиться к комнате " + code + ". Проверьте код или попробуйте ещё раз (у кого-то может быть строгий NAT)."); }, 35e3);
}
function guestRecv(m) {
  if (m.k === "lobby") { L = m.L; if (!L.started) { V = null; closeModal(); show("scRoom"); renderRoom(); } }
  else if (m.k === "st") { m.v.rcv = Date.now(); applyView(m.v); }
  else if (m.k === "emo") showEmo(m.s, m.e);
  else if (m.k === "toast") toastLocal(m.t);
  else if (m.k === "bye") leave(m.why || "Хост закрыл комнату");
}

/* ---- quick play: join an open room or create one ---- */
function quickPlay() { lsS("vName", myName()); NET.quick = 1; NET.qtry = 0; NET.err = ""; netOpen(); if (NET.st === "open") setTimeout(quickDecide, 400); menuUI(); }
function quickDecide() {
  if (!NET.quick || role !== "none" || NET.joining) return;
  const rs = [...NET.rooms.values()].filter((r) => r.n < r.mx && r.st === "lobby").sort((a, b) => b.n - a.n || (a.id < b.id ? -1 : 1));
  if (rs.length) guestJoin(rs[0].id, "online"); else hostOnline(true);
}
function quickRetry(code) { if (!NET.quick || role !== "none") return; NET.rooms.delete(code); if (++NET.qtry >= 4) { NET.quick = 0; menuUI(); return; } setTimeout(quickDecide, 700); }
function tieBreak() { // two players pressed "play online" at the same time and both made a room: the bigger code joins the smaller
  if (!NET.quickHost || role !== "host" || L.members.length > 1 || L.started) return;
  const o = [...NET.rooms.values()].filter((r) => r.id < L.code && r.st === "lobby" && r.n < r.mx).sort((a, b) => a.id < b.id ? -1 : 1)[0];
  if (o) { unhost(); role = "none"; L = null; NET.quick = 1; netOpen(); show("scMenu"); openNet("on"); guestJoin(o.id, "online"); }
}
function quickCancel() { NET.quick = 0; NET.err = ""; if (NET.joining) { NET.joining = 0; try { NET.ans && NET.ans.close(); } catch (e) { } } menuUI(); }

function leave(msg) {
  if (role === "host") { for (const p of peers.values()) { p.send({ k: "bye", why: "Хост закрыл комнату" }); } setTimeout(() => { for (const p of [...peers.values()]) p.close(); peers.clear(); }, 250); unhost(); }
  if (role === "guest" && hostPeer) { const hp = hostPeer; hostPeer = null; role = "none"; hp.close(); }
  role = "none"; G = null; L = null; V = null; NET.quick = 0; NET.quickHost = 0;
  closeModal(); show("scMenu"); menuStats(); NET.err = msg || ""; netOpen(); menuUI();
  if (msg) openNet();
}

/* ===================== GAME RULES (host) ===================== */
const BOTN = ["Робо-Лис", "Бот Ёжик", "Кибер-Сова", "Енот-3000"];
function newDeck() { const d = []; let id = 1; for (const c of COLORS) { d.push({ id: id++, c, v: "0" }); for (let k = 0; k < 2; k++) for (const v of ["1", "2", "3", "4", "5", "6", "7", "8", "9", "S", "R", "D"]) d.push({ id: id++, c, v }); } for (let k = 0; k < 4; k++) { d.push({ id: id++, c: "k", v: "W" }); d.push({ id: id++, c: "k", v: "F" }); } return shuffle(d); }
function startRound() {
  const hum = L.members.slice(0, 4), total = Math.min(4, Math.max(L.total, hum.length, 2));
  const H = hum.map((m) => ({ pid: m.pid, name: m.name, kind: "human", team: 0 })), B = [];
  for (let i = H.length, bi = 0; i < total; i++) B.push({ pid: null, name: BOTN[bi++], kind: "bot", team: 1 });
  let seats = [];
  if (L.mode === "coop") { while (H.length || B.length) { if (H.length) seats.push(H.shift()); if (B.length) seats.push(B.shift()); } }
  else seats = shuffle(H.concat(B));
  seats.forEach((s, i) => { s.hand = []; s.said = false; s.gift = 1; s.off = false; if (L.mode !== "coop") s.team = i; });
  G = { mode: L.mode, stack: L.stack, seats, deck: newDeck(), pile: [], turn: 0, dir: 1, color: "r", pend: 0, pendType: null, drawn: null, phase: "play", winner: -1, unsafe: -1, unsafeT: 0, catchAt: 0, ev: [], seq: G ? G.seq : 0, turnMs: 0, turnEnd: 0, botAt: 0 };
  G.turnMs = seats.some((s) => s.kind === "human" && s.pid !== "h") ? 30000 : 0;
  for (let k = 0; k < 7; k++) for (const s of seats) s.hand.push(G.deck.pop());
  const f = G.deck.splice(G.deck.findIndex((c) => /\d/.test(c.v)), 1)[0];
  G.pile.push(f); G.color = f.c;
  G.turn = Math.random() * seats.length | 0;
  L.started = true;
  G.ev.push({ t: "start" });
  startTurn();
  G.botAt = Date.now() + 2600; // let the deal animation finish
  sendLobby(); broadcastState(); advertise();
}
function startTurn() { G.drawn = null; G.turnEnd = G.turnMs ? Date.now() + G.turnMs : 0; G.botAt = Date.now() + rnd(900, 1600); G.ev.push({ t: "turn", s: G.turn }); }
const nidx = (k) => ((G.turn + G.dir * k) % G.seats.length + G.seats.length) % G.seats.length;
function nextTurn(skip) { G.turn = nidx(1 + skip); startTurn(); }
function give(s, n) {
  const S = G.seats[s], got = [];
  for (let i = 0; i < n; i++) { if (!G.deck.length) { const top = G.pile.pop(); G.deck = shuffle(G.pile); G.pile = [top]; if (!G.deck.length) break; } got.push(G.deck.pop()); }
  S.hand.push(...got); S.said = false; if (G.unsafe === s) G.unsafe = -1;
  return got;
}
function canPlay(c) {
  if (G.pend > 0) return G.stack && ((c.v === "D" && G.pendType === "D") || c.v === "F");
  const top = G.pile[G.pile.length - 1];
  return c.c === "k" || c.c === G.color || c.v === top.v;
}
const isEnemy = (a, b) => G.mode === "coop" ? G.seats[a].team !== G.seats[b].team : a !== b;
const ACT = {
  play(s, m) {
    if (G.turn !== s) return;
    const S = G.seats[s], i = S.hand.findIndex((c) => c.id === m.id);
    if (i < 0) return;
    const c = S.hand[i];
    if (G.drawn != null && G.drawn !== c.id) return;
    if (!canPlay(c)) return;
    if (c.c === "k" && !COLORS.includes(m.color)) return;
    S.hand.splice(i, 1); G.pile.push(c); G.color = c.c === "k" ? m.color : c.c;
    if (G.pile.length > 30) G.deck.unshift(...G.pile.splice(0, G.pile.length - 10));
    G.ev.push({ t: "play", s, c, color: G.color });
    if (S.hand.length === 1) { if (!S.said) { G.unsafe = s; G.unsafeT = Date.now(); G.catchAt = 0; } }
    else if (G.unsafe === s) G.unsafe = -1;
    S.said = false;
    if (!S.hand.length) { endRound(s); return 1; }
    let skip = 0;
    if (c.v === "S") { skip = 1; G.ev.push({ t: "skip", s: nidx(1) }); }
    else if (c.v === "R") { if (G.seats.length === 2) { skip = 1; G.ev.push({ t: "skip", s: nidx(1) }); } else G.dir *= -1; G.ev.push({ t: "rev", dir: G.dir }); }
    else if (c.v === "D") { G.pend += 2; G.pendType = "D"; }
    else if (c.v === "F") { G.pend += 4; G.pendType = "F"; }
    nextTurn(skip);
    if (G.pend && !G.stack) { const v = G.turn; give(v, G.pend); G.ev.push({ t: "draw", s: v, n: G.pend }); G.pend = 0; G.pendType = null; nextTurn(0); }
    return 1;
  },
  draw(s) {
    if (G.turn !== s || G.drawn != null) return;
    if (G.pend > 0) { const n = G.pend; give(s, n); G.ev.push({ t: "draw", s, n }); G.pend = 0; G.pendType = null; nextTurn(0); return 1; }
    const got = give(s, 1);
    G.ev.push({ t: "draw", s, n: got.length });
    if (got[0] && canPlay(got[0])) { G.drawn = got[0].id; G.botAt = Date.now() + 700; }
    else nextTurn(0);
    return 1;
  },
  pass(s) { if (G.turn !== s || G.drawn == null) return; G.ev.push({ t: "pass", s }); nextTurn(0); return 1; },
  call(s) {
    const S = G.seats[s];
    if (G.unsafe === s) { G.unsafe = -1; G.ev.push({ t: "call", s }); return 1; }
    if (S.hand.length === 2 && G.turn === s && !S.said) { S.said = true; G.ev.push({ t: "call", s }); return 1; }
  },
  catch(s) {
    const v = G.unsafe;
    if (v < 0 || v === s || !isEnemy(s, v) || Date.now() - G.unsafeT < 300) return;
    give(v, 2); G.unsafe = -1; G.ev.push({ t: "caught", s: v, by: s });
    return 1;
  },
  gift(s, m) {
    const S = G.seats[s], to = m.to | 0, T = G.seats[to];
    if (G.mode !== "coop" || G.turn !== s || G.pend || G.drawn != null || S.gift < 1 || !T || to === s || T.team !== S.team || S.hand.length < 3) return;
    const i = S.hand.findIndex((c) => c.id === m.id); if (i < 0) return;
    T.hand.push(S.hand.splice(i, 1)[0]); S.gift--; T.said = false; if (G.unsafe === to) G.unsafe = -1;
    G.ev.push({ t: "gift", s, to }); nextTurn(0);
    return 1;
  },
};
function act(s, m) { if (!G || G.phase !== "play" || !ACT[m.a]) return; if (ACT[m.a](s, m)) broadcastState(); }
function endRound(s) {
  G.phase = "over"; G.winner = s; G.turnEnd = 0; G.unsafe = -1;
  const W = G.seats[s], k = G.mode === "coop" ? (W.team === 0 ? "Команда людей" : "Команда ботов") : W.name;
  L.score[k] = (L.score[k] || 0) + 1;
  G.ev.push({ t: "win", s });
}
/* ---- bots (and players who dropped out) ---- */
function bestColor(h) { const n = { r: 0, y: 0, g: 0, b: 0 }; for (const c of h) if (c.c !== "k") n[c.c] += 1 + (c.v > "9" ? .3 : 0); let b = COLORS[Math.random() * 4 | 0], mx = 0; for (const c of COLORS) if (n[c] > mx) { mx = n[c]; b = c; } return b; }
function botMove(s) {
  const S = G.seats[s];
  if (G.drawn != null) { const c = S.hand.find((x) => x.id === G.drawn); if (c && canPlay(c)) { act(s, { a: "play", id: c.id, color: bestColor(S.hand) }); } else act(s, { a: "pass" }); return; }
  const opts = S.hand.filter(canPlay);
  if (!opts.length) { act(s, { a: "draw" }); return; }
  const nx = nidx(1), N = G.seats[nx], foe = isEnemy(s, nx), cnt = { r: 0, y: 0, g: 0, b: 0, k: 0 };
  for (const c of S.hand) cnt[c.c]++;
  let best = null, bs = -1e9;
  for (const c of opts) {
    let sc = Math.random() * 1.2;
    if (c.v === "S" || c.v === "D") sc += foe ? (N.hand.length <= 3 ? 7 : 2) : -6;
    else if (c.v === "R") sc += 1;
    if (c.c === "k") sc += (S.hand.length <= 2 ? 4 : -4) + (c.v === "F" ? (foe ? (N.hand.length <= 3 ? 6 : 0) : -7) : 0);
    else sc += cnt[c.c] * .7 + (/\d/.test(c.v) ? +c.v * .08 : 0);
    if (G.pend) sc += 10;
    if (sc > bs) { bs = sc; best = c; }
  }
  if (S.hand.length === 2 && Math.random() < .82) { S.said = true; G.ev.push({ t: "call", s }); }
  act(s, { a: "play", id: best.id, color: bestColor(S.hand.filter((x) => x.id !== best.id)) });
}
function hostTick() {
  if (!G || G.phase !== "play" || (role !== "host" && role !== "solo")) return;
  const now = Date.now(), S = G.seats[G.turn];
  if (G.unsafe >= 0) {
    if (now - G.unsafeT > 7000) { G.unsafe = -1; broadcastState(); return; }
    const bots = G.seats.map((x, i) => i).filter((i) => (G.seats[i].kind === "bot" || G.seats[i].off) && isEnemy(i, G.unsafe));
    if (bots.length) {
      if (!G.catchAt) G.catchAt = now + rnd(1500, 3400);
      else if (now >= G.catchAt) { G.catchAt = 0; act(bots[Math.random() * bots.length | 0], { a: "catch" }); return; }
    }
  }
  if ((S.kind === "bot" || S.off) && now >= G.botAt) { botMove(G.turn); return; }
  if (G.turnEnd && now > G.turnEnd && S.kind === "human" && !S.off) { act(G.turn, { a: G.drawn != null ? "pass" : "draw" }); if (G.phase === "play" && G.turn === G.seats.indexOf(S) && G.drawn != null) act(G.turn, { a: "pass" }); }
}
setInterval(hostTick, 200);

function viewFor(pid) {
  const me = G.seats.findIndex((s) => s.pid === pid), coop = G.mode === "coop";
  return {
    me, mode: G.mode, stack: G.stack, code: L.code,
    seats: G.seats.map((s, i) => ({ name: s.name, kind: s.kind, off: s.off, team: s.team, n: s.hand.length, said: s.said, gift: s.gift,
      hand: (i === me || (coop && me >= 0 && s.team === G.seats[me].team)) ? s.hand : null })),
    top: G.pile[G.pile.length - 1], under: G.pile.slice(-4, -1), deckN: G.deck.length,
    turn: G.turn, dir: G.dir, color: G.color, pend: G.pend, pendType: G.pendType, drawn: G.turn === me ? G.drawn : null,
    phase: G.phase, winner: G.winner, unsafe: G.unsafe, tl: G.turnEnd ? G.turnEnd - Date.now() : 0, tmax: G.turnMs,
    ev: G.ev, seq: G.seq, score: L.score, isHost: pid === "h",
  };
}
function broadcastState() {
  if (!G) return;
  G.seq++;
  for (const [pid, p] of peers) p.send({ k: "st", v: viewFor(pid) });
  const v = viewFor("h"); v.rcv = Date.now(); G.ev = [];
  applyView(v);
}
function sendAct(m) {
  if (role === "guest") { hostPeer && hostPeer.send(Object.assign({ k: "act" }, m)); }
  else if (G) { const s = G.seats.findIndex((x) => x.pid === "h"); if (s >= 0) act(s, m); }
}
const EMOS = ["👍", "😂", "😮", "😡", "🎉", "🤝", "😭", "🔥"];
function sendEmo(e) { $("emoBar").classList.remove("on"); if (role === "guest") hostPeer && hostPeer.send({ k: "emo", e }); else hostEmo("h", e); }

/* ===================== RENDER: menu & room ===================== */
function menuUI() {
  const bz = !!(NET.quick || NET.joining);
  $("bQuick").style.display = bz ? "none" : ""; $("bQuickC").style.display = bz ? "" : "none";
  for (const id of ["bHost", "bJoinCode", "bQrHost", "bQrScan", "bQrPhoto"]) $(id).disabled = bz;
  let t = NET.joining ? "Подключаюсь к комнате…" : NET.quick ? "Ищем игру…" : NET.st === "open" ? "Онлайн — выберите комнату или нажмите «Играть онлайн»" : NET.st === "conn" ? "Подключаюсь к сервису поиска…" : "Поиск не запущен";
  $("nst").textContent = t; $("nst").classList.toggle("bz", /…$/.test(t)); $("nst").classList.toggle("ok", NET.st === "open" && !bz);
  $("nerr").textContent = NET.err || "";
  const el = $("rooms"), rs = [...NET.rooms.values()].sort((a, b) => (a.st === "lobby" ? 0 : 1) - (b.st === "lobby" ? 0 : 1) || b.n - a.n);
  $("rcnt").textContent = rs.length ? rs.length : "";
  el.textContent = "";
  if (!rs.length) { const d = document.createElement("p"); d.className = "nem"; d.textContent = "Пока комнат нет. Создай свою — друзья увидят её здесь."; el.appendChild(d); }
  for (const r of rs) {
    const row = document.createElement("div"), s = document.createElement("span"), b = document.createElement("button");
    row.className = "rmr";
    s.innerHTML = "🎮 " + esc(r.name) + "<small>код " + esc(r.id) + " · " + r.n + "/" + r.mx + " · " + (r.st === "game" ? "идёт игра" : "ждут игроков") + "</small>";
    b.className = "nb pr"; b.textContent = r.n >= r.mx ? "Полная" : "Играть"; b.disabled = r.n >= r.mx || bz;
    b.onclick = () => guestJoin(r.id, "online");
    row.append(s, b); el.appendChild(row);
  }
  recRender();
}
function menuStats() {
  $("mmst").innerHTML = '<i class="ic">' + ICON.trophy + "</i><span>Побед: <b>" + (lsG("vWins") || 0) + "</b> · раундов: <b>" + (lsG("vGames") || 0) + "</b></span>";
  const r = recLoad()[0], b = $("bRep");
  b.style.display = r ? "" : "none";
  if (r) $("bRepL").textContent = (r.r === "host" ? "Хост" : "Гость") + " · " + REC_V[r.v] + (r.n ? " · " + r.n : "") + (r.w ? " · «" + r.w + "»" : "");
}
function seg(el, items, cur, on, can) {
  el.innerHTML = items.map(([v, t]) => '<button class="nb' + (v === cur ? " ac" : "") + '" data-v="' + v + '"' + (can ? "" : " disabled") + "><b>" + t + "</b></button>").join("");
  el.onclick = (e) => { const b = e.target.closest("button"); if (!b || !can) return; uiClick(); on(b.dataset.v); };
}
function renderRoom() {
  if (!L) return;
  const host = role !== "guest", online = role !== "solo";
  $("rIco").textContent = online ? "📡" : "🤖";
  $("rTitle").innerHTML = online ? 'Комната<span class="code">' + esc(L.code) + "</span>" : "Игра с ботами";
  $("rHint").textContent = online ? (host ? "Друзья: «По сети» → QR (сканировать), или «Код» → " + L.code + ", или просто «Играть онлайн»." : "Ты в комнате. Хост настраивает игру.") : "Ты против ботов. Настрой стол и начинай!";
  const showQR = online && host && !L.started && L.members.length < 4;
  $("rQR").style.display = showQR ? "" : "none";
  if (showQR && $("rQRc").dataset.c !== L.code) { qrDraw($("rQRc"), "UNIK1:" + L.code); $("rQRc").dataset.c = L.code; }
  const total = Math.min(4, Math.max(L.total, L.members.length, 2)), coop = L.mode === "coop";
  let h = "";
  for (let i = 0; i < 4; i++) {
    const m = L.members[i];
    if (m) h += '<div class="slot">' + avatar(m.name, i) + "<span>" + esc(m.name) + (m.pid === "h" ? " 👑" : "") + "</span>" + (coop ? '<span class="tag">Люди</span>' : "") + "</div>";
    else if (i < total) h += '<div class="slot bot">' + avatar("", i, 1) + "<span>" + BOTN[i - L.members.length] + "</span>" + (coop ? '<span class="tag t1">Боты</span>' : "") + "</div>";
    else h += '<div class="slot empty"><div class="av" style="background:#ccc">·</div><span>Свободно</span></div>';
  }
  $("slots").innerHTML = h;
  const set = (k, v) => { L[k] = v; sendLobby(); };
  seg($("oTotal"), [[2, "2"], [3, "3"], [4, "4"]], total, (v) => set("total", +v), host);
  seg($("oMode"), [["coop", "🤝 Кооп: люди vs боты"], ["ffa", "⚔ Каждый за себя"]], L.mode, (v) => set("mode", v), host);
  seg($("oStack"), [["1", "Вкл"], ["0", "Выкл"]], L.stack ? "1" : "0", (v) => set("stack", v === "1"), host);
  $("bStart").style.display = host ? "" : "none";
  $("rWait").textContent = host ? (online && L.members.length < 2 ? "Можно начинать и одному — места займут боты. Друзья смогут зайти в следующем раунде." : "") : "⏳ Ждём, пока хост начнёт игру…";
}

/* ===================== ОДИН QR НА ВСЕХ (как в новой версии Stick Fight) =====================
   В QR лежит только код комнаты. Обмен служебными данными идёт через интернет (ntfy.sh),
