function myHandSorted() { const o = { r: 0, y: 1, g: 2, b: 3, k: 4 }, vo = "0123456789SRDWF"; return V.me >= 0 ? V.seats[V.me].hand.slice().sort((a, b) => o[a.c] - o[b.c] || vo.indexOf(a.v) - vo.indexOf(b.v)) : []; }
